+import type { AnyColumn, GetColumnData } from '~/column.ts';
+import { sql, type SQL, type SQLWrapper } from '../sql.ts';
+
+export type WindowOrderBy = SQLWrapper;
+
+export interface WindowSpec {
+	partitionBy?: WindowOrderBy | WindowOrderBy[];
+	orderBy?: WindowOrderBy | WindowOrderBy[];
+	frame?: WindowFrame;
+}
+
+export interface WindowDefinition {
+	name: string;
+	spec: WindowSpec;
+}
+
+type FrameBoundaryKind = 'unbounded preceding' | 'current row' | 'unbounded following' | 'preceding' | 'following';
+
+export class WindowFrameBoundary {
+	/** @internal */
+	constructor(readonly kind: FrameBoundaryKind, readonly offset?: number) {}
+
+	/** @internal */
+	get position(): number {
+		if (this.kind === 'unbounded preceding') return -Infinity;
+		if (this.kind === 'current row') return 0;
+		if (this.kind === 'unbounded following') return Infinity;
+		return this.kind === 'preceding' ? -this.offset! : this.offset!;
+	}
+
+	/** @internal */
+	getSQL(): SQL {
+		return this.offset === undefined ? sql.raw(this.kind) : sql.raw(`${this.offset} ${this.kind}`);
+	}
+}
+
+export const unboundedPreceding = new WindowFrameBoundary('unbounded preceding');
+export const currentRow = new WindowFrameBoundary('current row');
+export const unboundedFollowing = new WindowFrameBoundary('unbounded following');
+
+function offsetBoundary(name: 'preceding' | 'following', offset: number): WindowFrameBoundary {
+	if (!Number.isInteger(offset) || offset < 0) {
+		throw new Error(`${name}() requires a non-negative integer, received ${offset}`);
+	}
+	return new WindowFrameBoundary(name, offset);
+}
+
+export function preceding(offset: number): WindowFrameBoundary {
+	return offsetBoundary('preceding', offset);
+}
+
+export function following(offset: number): WindowFrameBoundary {
+	return offsetBoundary('following', offset);
+}
+
+export class WindowFrame implements SQLWrapper {
+	/** @internal */
+	constructor(readonly type: 'rows' | 'range', readonly from: WindowFrameBoundary, readonly to: WindowFrameBoundary) {}
+
+	getSQL(): SQL {
+		return sql`${sql.raw(this.type)} between ${this.from} and ${this.to}`;
+	}
+}
+
+function frame(type: 'rows' | 'range', spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	if (spec.from.position > spec.to.position) {
+		throw new Error('Window frame "from" boundary must not be ordered after "to"');
+	}
+	return new WindowFrame(type, spec.from, spec.to);
+}
+
+export function rows(spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	return frame('rows', spec);
+}
+
+export function range(spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	return frame('range', spec);
+}
+
+export function buildWindowSpec(spec: WindowSpec): SQL {
+	const partitionBy = spec.partitionBy === undefined ? [] : Array.isArray(spec.partitionBy) ? spec.partitionBy : [spec.partitionBy];
+	const orderBy = spec.orderBy === undefined ? [] : Array.isArray(spec.orderBy) ? spec.orderBy : [spec.orderBy];
+	const partitionSql = partitionBy.length ? sql`partition by ${sql.join(partitionBy, sql`, `)}` : undefined;
+	const orderSql = orderBy.length ? sql`order by ${sql.join(orderBy, sql`, `)}` : undefined;
+	return sql.join([partitionSql, orderSql, spec.frame].filter((value): value is SQLWrapper => value !== undefined), sql` `);
+}
+
+export class WindowFunction<T> {
+	/** @internal */
+	constructor(private readonly expression: SQL) {}
+
+	over(): SQL<T>;
+	over(spec: WindowSpec): SQL<T>;
+	over(name: string): SQL<T>;
+	over(spec: WindowSpec | string = {}): SQL<T> {
+		return typeof spec === 'string'
+			? sql`${this.expression} over ${sql.identifier(spec)}`
+			: sql`${this.expression} over (${buildWindowSpec(spec)})`;
+	}
+}
+
+type WindowValue<T extends SQLWrapper> = T extends AnyColumn ? GetColumnData<T> : T extends SQL<infer TValue> ? TValue : unknown;
+
+function functionBuilder<T>(name: string, args: SQLWrapper[] = []): WindowFunction<T> {
+	return new WindowFunction(sql`${sql.raw(name)}(${sql.join(args, sql`, `)})`);
+}
+
+function positional(name: string, value: number): SQLWrapper {
+	return sql.raw(String(value));
+}
+
+function positiveInteger(name: 'ntile' | 'nthValue', value: number): void {
+	if (!Number.isInteger(value) || value <= 0) {
+		throw new Error(`${name}() requires a positive integer, received ${value}`);
+	}
+}
+
+export function rowNumber(): WindowFunction<number> { return functionBuilder('row_number'); }
+export function rank(): WindowFunction<number> { return functionBuilder('rank'); }
+export function denseRank(): WindowFunction<number> { return functionBuilder('dense_rank'); }
+export function ntile(buckets: number): WindowFunction<number> {
+	positiveInteger('ntile', buckets);
+	return functionBuilder('ntile', [positional('ntile', buckets)]);
+}
+export function percentRank(): WindowFunction<number> { return functionBuilder('percent_rank'); }
+export function cumeDist(): WindowFunction<number> { return functionBuilder('cume_dist'); }
+
+export function lag<T extends SQLWrapper>(value: T): WindowFunction<WindowValue<T> | null>;
+export function lag<T extends SQLWrapper>(value: T, offset: number): WindowFunction<WindowValue<T> | null>;
+export function lag<T extends SQLWrapper, TDefault extends SQLWrapper>(value: T, offset: number, defaultValue: TDefault): WindowFunction<WindowValue<T>>;
+export function lag<T extends SQLWrapper>(value: T, offset?: number, defaultValue?: SQLWrapper): WindowFunction<WindowValue<T> | null> {
+	return functionBuilder('lag', [value, ...(offset === undefined ? [] : [positional('lag', offset)]), ...(defaultValue === undefined ? [] : [defaultValue])]);
+}
+export function lead<T extends SQLWrapper>(value: T): WindowFunction<WindowValue<T> | null>;
+export function lead<T extends SQLWrapper>(value: T, offset: number): WindowFunction<WindowValue<T> | null>;
+export function lead<T extends SQLWrapper, TDefault extends SQLWrapper>(value: T, offset: number, defaultValue: TDefault): WindowFunction<WindowValue<T>>;
+export function lead<T extends SQLWrapper>(value: T, offset?: number, defaultValue?: SQLWrapper): WindowFunction<WindowValue<T> | null> {
+	return functionBuilder('lead', [value, ...(offset === undefined ? [] : [positional('lead', offset)]), ...(defaultValue === undefined ? [] : [defaultValue])]);
+}
+export function firstValue<T extends SQLWrapper>(value: T): WindowFunction<WindowValue<T> | null> { return functionBuilder('first_value', [value]); }
+export function lastValue<T extends SQLWrapper>(value: T): WindowFunction<WindowValue<T> | null> { return functionBuilder('last_value', [value]); }
+export function nthValue<T extends SQLWrapper>(value: T, n: number): WindowFunction<WindowValue<T> | null> {
+	positiveInteger('nthValue', n);
+	return functionBuilder('nth_value', [value, positional('nthValue', n)]);
+}
+export function windowSum(value: SQLWrapper): WindowFunction<string | null> { return functionBuilder('sum', [value]); }
+export function windowAvg(value: SQLWrapper): WindowFunction<string | null> { return functionBuilder('avg', [value]); }
+export function windowMin<T extends SQLWrapper>(value: T): WindowFunction<WindowValue<T> | null> { return functionBuilder('min', [value]); }
+export function windowMax<T extends SQLWrapper>(value: T): WindowFunction<WindowValue<T> | null> { return functionBuilder('max', [value]); }
+export function windowCount(value?: SQLWrapper): WindowFunction<number> { return functionBuilder('count', value === undefined ? [sql.raw('*')] : [value]); }
